/* TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Tom; Brendon (integrator) added the marked wrap fix (30 Oct 2026) and hard-tune mode for the Autotune (PitchShifter_SetHardTune, ps_hard_tune_wet_mix; 30 Oct 2026), with an AI coding assistant. */
/*
 * Granular pitch shifter: plays the sound back higher or lower by a ratio
 * without changing its speed. No task of its own: audio_effects.c calls it
 * for Autotune, Pitch up and Pitch down, inside FxRenderTask. Samples are
 * 16-bit PCM (plain signed sample values) at 48 kHz.
 *
 * The idea:
 *   - The input goes into a circular delay line, and a read head plays it
 *     back at `ratio` stored samples per output sample: faster than it was
 *     written raises the pitch (ratio > 1), slower lowers it (ratio < 1).
 *     So the head's delay behind the newest sample changes by (1 - ratio)
 *     every sample.
 *   - A faster head would catch up with the newest sample and a slower one
 *     would fall further and further behind, so its delay is kept between
 *     32 and 288 samples: at one end it jumps 256 samples to the other end,
 *     which replays (pitch up) or skips (pitch down) 5.3 ms of sound. The
 *     stretch between two jumps is a grain: about 11 ms for Pitch up
 *     (+7 semitones) and 16 ms for Pitch down (-7).
 *   - A jump would click, so there are TWO heads, half a grain apart, each
 *     faded by a smooth window that is 0 at its jump and 1 half way between
 *     its jumps. The two weights always add up to 1: while one head jumps
 *     unheard, the other plays at full level (a crossfade).
 *
 * Per sample (PitchShifter_ProcessBlock):
 *   1. store the input sample in the delay line
 *   2. glide the ratio towards the target (PS_RATIO_SMOOTHING); in
 *      hard-tune mode (Autotune) jump straight to it
 *   3. read both heads (linear interpolation between stored samples) and
 *      crossfade them
 *   4. close to ratio 1, blend the clean input back in
 *      (PS_FULL_WET_RATIO_ERROR); in hard-tune mode the output is fully
 *      shifted, and fades to the dry input only while the ratio is
 *      released to exactly 1 (ps_hard_tune_wet_mix)
 *   5. move the heads: phase += (1 - ratio) / 256, kept inside 0..1
 *
 * Tests: Tests/AudioEffects/test_pitch_shifter.c.
 */
#include "pitch_shifter.h"

#include <math.h>
#include <string.h>

/* Slower ratio movement reduces zippering when autotune changes target.
 * Each sample the ratio moves 0.1 % of the way to the target (a one-pole
 * low-pass): a time constant of about 1000 samples, 21 ms. Zippering = a
 * rough, stepped sound when a setting jumps. */
#define PS_RATIO_SMOOTHING          0.0010f
/* Keep a wider dry/shifted transition around unity.
 * Within 0.8 % of ratio 1 (about 14 cents; a cent is 1/100 of a semitone)
 * the output is a blend of the dry input and the shifted sound, all dry at
 * exactly 1: there the heads stand still and would only replay two delayed
 * copies of the input. */
#define PS_FULL_WET_RATIO_ERROR     0.0080f
/* Hard tune: how fast the dry input fades in or out when the ratio is
 * released or taken up again: a straight-line fade over 480 samples
 * (10 ms), slow enough not to click. */
#define PS_HARD_TUNE_DRY_STEP       (1.0f / 480.0f)

/** Convert a float sample to signed 16-bit PCM with saturation and rounding. */
static int16_t ps_saturate_i16(float value)
{
    if (value > 32767.0f) return INT16_MAX;
    if (value < -32768.0f) return INT16_MIN;
    return (int16_t)(value >= 0.0f ? value + 0.5f : value - 0.5f);
}

/** Return the smooth complementary grain window for a normalised phase. */
static float ps_smooth_window(float phase)
{
    /*
     * Smooth triangular crossfade with zero slope at grain hand-off points.
     * Two heads separated by 0.5 phase remain complementary, but unlike a
     * linear triangle this avoids sharp slope changes that can sound clicky
     * on complex speech.
     * t * t * (3 - 2 t) is the "smoothstep" curve: from 0 to 1 like a
     * straight line, but flat at both ends. It rises over the first half of
     * the grain and falls over the second, so it is 0 at phases 0 and 1
     * (where the head jumps) and 1 at phase 0.5; w(p) + w(p + 0.5) = 1 for
     * every p.
     */
    float t;
    if (phase < 0.5f)
    {
        t = 2.0f * phase;
        return t * t * (3.0f - (2.0f * t));
    }

    t = 2.0f * (phase - 0.5f);
    return 1.0f - (t * t * (3.0f - (2.0f * t)));
}

/** Clamp a floating-point value to the inclusive range 0..1. */
static float ps_clamp01(float x)
{
    if (x < 0.0f) return 0.0f;
    if (x > 1.0f) return 1.0f;
    return x;
}

/**
 * Hard tune, one sample: how much of the shifted sound to play (0..1).
 * While Autotune asks for a correction, all of it. When it releases the
 * ratio to exactly 1 (no voice for 150 ms), the heads stop moving and sit
 * 128 samples apart; their sum would colour breaths and pauses like a comb
 * filter. So then the dry input fades in, and fades out again when a
 * correction is asked for.
 */
static float ps_hard_tune_wet_mix(PitchShifter *shifter)
{
    if (shifter->target_ratio == 1.0f)
    {
        shifter->dry_mix = fminf(1.0f, shifter->dry_mix + PS_HARD_TUNE_DRY_STEP);
    }
    else
    {
        shifter->dry_mix = fmaxf(0.0f, shifter->dry_mix - PS_HARD_TUNE_DRY_STEP);
    }
    return 1.0f - shifter->dry_mix;
}

/**
 * @brief Read the circular delay line at a fractional sample delay.
 * @param shifter Persistent pitch-shifter state.
 * @param delay_samples Delay behind the current write head in samples.
 * @return Linearly interpolated sample.
 *
 * Linear interpolation: a delay of 10.25 samples gives 75 % of the sample
 * 10 back plus 25 % of the sample 11 back (a straight line between them).
 */
static float ps_read_fractional_delay(const PitchShifter *shifter, float delay_samples)
{
    float read_position = (float)shifter->write_index - delay_samples;

    while (read_position < 0.0f)
    {
        read_position += (float)PITCH_SHIFTER_BUFFER_SIZE;
    }
    /* TEAM CODE (written by Brendon, integrator, 30 Oct 2026, best-ui): the wrap below.
     * A read position a hair below 0 (say -0.00001) plus 1024 rounds to
     * exactly 1024.0f in float. index0 would then be 1024, one past the end
     * of delay_buffer, and the read would take write_index and the padding
     * bytes after it (inside AudioEffectsState those bytes can hold an old
     * echo sample: a loud click). Position 1024 is position 0 of the ring. */
    if (read_position >= (float)PITCH_SHIFTER_BUFFER_SIZE)
    {
        read_position -= (float)PITCH_SHIFTER_BUFFER_SIZE;
    }
    const uint16_t index0 = (uint16_t)read_position;
    const uint16_t index1 = (uint16_t)((index0 + 1U) % PITCH_SHIFTER_BUFFER_SIZE);
    const float fraction = read_position - (float)index0;

    return shifter->delay_buffer[index0]
         + fraction * (shifter->delay_buffer[index1] - shifter->delay_buffer[index0]);
}

/**
 * @brief Initialise delay history and unity pitch ratio.
 * @param shifter Shifter state; NULL is safely ignored.
 */
void PitchShifter_Init(PitchShifter *shifter)
{
    PitchShifter_Reset(shifter);
}

/**
 * @brief Clear delay history and restore unity pitch ratio.
 * @param shifter Shifter state; NULL is safely ignored.
 */
void PitchShifter_Reset(PitchShifter *shifter)
{
    if (shifter == NULL)
    {
        return;
    }

    memset(shifter->delay_buffer, 0, sizeof(shifter->delay_buffer));
    shifter->write_index = 0U;
    shifter->phase = 0.0f;
    shifter->current_ratio = 1.0f;
    shifter->target_ratio = 1.0f;
    shifter->hard_tune = false;
    shifter->dry_mix = 1.0f;     /* hard tune starts released: the dry input */
}

/**
 * @brief Switch hard-tune mode (no glide, no dry blend) on or off.
 * @param shifter Shifter state; NULL is safely ignored.
 * @param hard_tune true to switch it on.
 */
void PitchShifter_SetHardTune(PitchShifter *shifter, bool hard_tune)
{
    if (shifter != NULL)
    {
        shifter->hard_tune = hard_tune;
    }
}

/**
 * @brief Validate and store a target pitch ratio.
 * @param shifter Persistent shifter state.
 * @param ratio Requested pitch ratio.
 * @return true when accepted, false for invalid input.
 */
bool PitchShifter_SetRatio(PitchShifter *shifter, float ratio)
{
    if ((shifter == NULL) || (!isfinite(ratio)) ||
        (ratio < PITCH_SHIFTER_MIN_RATIO) || (ratio > PITCH_SHIFTER_MAX_RATIO))
    {
        return false;
    }

    shifter->target_ratio = ratio;
    return true;
}

/**
 * @brief Process one block with the dual-read-head granular shifter.
 * @param shifter Persistent shifter state.
 * @param input Signed 16-bit PCM input.
 * @param output Signed 16-bit PCM output.
 * @param sample_count Number of samples; must be greater than zero.
 * @return true on success, false for invalid inputs.
 */
bool PitchShifter_ProcessBlock(PitchShifter *shifter,
                               const int16_t *input,
                               int16_t *output,
                               size_t sample_count)
{
    if ((shifter == NULL) || (input == NULL) || (output == NULL) || (sample_count == 0U))
    {
        return false;
    }

    for (size_t i = 0U; i < sample_count; ++i)
    {
        /* 1. Store the newest input sample. */
        const float dry = (float)input[i];
        shifter->delay_buffer[shifter->write_index] = dry;

        /* 2. Glide the ratio 0.1 % of the way to the target; hard tune:
         *    use the target at once (a clean jump from note to note). */
        if (shifter->hard_tune)
        {
            shifter->current_ratio = shifter->target_ratio;
        }
        else
        {
            shifter->current_ratio += PS_RATIO_SMOOTHING
                                    * (shifter->target_ratio - shifter->current_ratio);
        }

        const float ratio_error = fabsf(shifter->current_ratio - 1.0f);
        /* 3. The two heads: head 2 is half a grain (phase 0.5) on from head 1. */
        const float phase1 = shifter->phase;
        float phase2 = phase1 + 0.5f;
        if (phase2 >= 1.0f) phase2 -= 1.0f;

        /*
         * One continuous delay mapping is used for both directions. The signed
         * phase step crosses smoothly through zero at ratio == 1, avoiding the
         * read-head remapping discontinuity that could pop in v2.
         * Each head's delay = 32 + phase x 256 samples (0.7 to 6 ms), read
         * with interpolation and weighted by its crossfade window.
         */
        const float delay1 = PITCH_SHIFTER_MIN_DELAY_SAMPLES
                           + phase1 * PITCH_SHIFTER_GRAIN_SAMPLES;
        const float delay2 = PITCH_SHIFTER_MIN_DELAY_SAMPLES
                           + phase2 * PITCH_SHIFTER_GRAIN_SAMPLES;

        const float weight1 = ps_smooth_window(phase1);
        const float weight2 = ps_smooth_window(phase2);
        const float shifted = (weight1 * ps_read_fractional_delay(shifter, delay1))
                            + (weight2 * ps_read_fractional_delay(shifter, delay2));

        /* 4. Close to ratio 1, blend back to the dry input (all dry at 1).
         *    Hard tune: always all shifted. (A blend there would mix the
         *    undelayed dry input with the 0.7-6 ms delayed heads whenever a
         *    jump lands near ratio 1, and partly undo small corrections.) */
        const float wet_mix = shifter->hard_tune
                            ? ps_hard_tune_wet_mix(shifter)
                            : ps_clamp01(ratio_error / PS_FULL_WET_RATIO_ERROR);
        const float mixed = ((1.0f - wet_mix) * dry) + (wet_mix * shifted);
        output[i] = ps_saturate_i16(mixed);

        /* 5. Move the heads: each delay changes by (1 - ratio) samples, so
         * each head reads `ratio` stored samples per output sample. When
         * phase wraps, a head jumps by 256 samples, just where its weight
         * is 0. */
        shifter->phase += (1.0f - shifter->current_ratio)
                        / PITCH_SHIFTER_GRAIN_SAMPLES;
        while (shifter->phase >= 1.0f)
        {
            shifter->phase -= 1.0f;
        }
        while (shifter->phase < 0.0f)
        {
            shifter->phase += 1.0f;
        }

        shifter->write_index++;
        if (shifter->write_index >= PITCH_SHIFTER_BUFFER_SIZE)
        {
            shifter->write_index = 0U;
        }
    }

    return true;
}
